const { withProjectBuildGradle } = require('@expo/config-plugins');

// react-native-google-mobile-ads 16.x pulls play-services-ads 25.x, whose bundled
// .kotlin_module files are newer than the Kotlin compiler Expo SDK 54 / RN 0.81 builds with
// ("Module was compiled with an incompatible version of Kotlin"), which fails
// :react-native-google-mobile-ads:compileReleaseKotlin. The library's own Kotlin only calls
// the SDK's Java API, so skipping the metadata version check for THAT module is enough.
// android/ is regenerated by `expo prebuild`, so the patch lives here and is re-applied.
const MARKER = '// withKotlinMetadataSkip';
const SNIPPET = `
${MARKER}
subprojects { sp ->
  if (sp.name == 'react-native-google-mobile-ads') {
    sp.tasks.configureEach { t ->
      if (t.name.startsWith('compile') && t.name.endsWith('Kotlin') && t.hasProperty('compilerOptions')) {
        t.compilerOptions.freeCompilerArgs.add('-Xskip-metadata-version-check')
      }
    }
  }
}
`;

module.exports = function withKotlinMetadataSkip(config) {
  return withProjectBuildGradle(config, (config) => {
    if (!config.modResults.contents.includes(MARKER)) config.modResults.contents += SNIPPET;
    return config;
  });
};
